<template>
 <div class="hx-workspace" v-loading="loading">
  <header class="hx-header"><div><div class="hx-eyebrow">禾序商贸 · DISTRIBUTION OPERATIONS</div><h1>{{config.title}}</h1><p>{{activeTab==='backups'?'平台级加密备份，覆盖整个联调数据库':config.subtitle}}</p></div><div class="hx-tools"><el-select v-if="activeTab!=='backups'" v-model="shopId" :disabled="saving||uploading" @change="statementBatch='';load()" style="width:220px" aria-label="选择商城"><el-option v-if="platformPointPaths.includes(activeTab)" :value="0" label="平台积分（需平台权限）"/><el-option v-for="shop in shops" :key="shop.id" :value="shop.id" :label="shop.name"/></el-select><el-button @click="load">刷新数据</el-button></div></header>
  <el-alert v-if="error&&module!=='overview'&&module!=='applications'" :title="error" type="error" :closable="false" show-icon/>
  <template v-if="module==='overview'&&!error"><div class="hx-metrics"><article v-for="m in metrics" :key="m.label"><span>{{m.label}}</span><strong>{{m.value}}</strong><small>{{m.note}}</small></article></div><section class="hx-section"><div class="hx-section-heading"><h2>订单处理中心</h2><el-tag type="success">数据库实时数据</el-tag></div><el-table :data="recentOrders" empty-text="当前商城暂无订单"><el-table-column prop="id" label="订单编号" min-width="230"/><el-table-column label="订单类型"><template #default="{row}">{{labels[row.order_type]||row.order_type}}</template></el-table-column><el-table-column label="应付金额"><template #default="{row}">¥{{money(row.total)}}</template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag>{{row.status==='PAID'&&row.group?.status==='FORMING'?'待成团':labels[row.status]||row.status}}</el-tag></template></el-table-column><el-table-column label="创建时间" min-width="190"><template #default="{row}">{{workspaceListCell('created_at',row.created_at)}}</template></el-table-column></el-table></section><div class="hx-notes"><article><h3>独立收款与账本</h3><p>直营零售、公司批发和经销商商城按订单类型、商城ID分别记录。</p></article><article><h3>库存与履约</h3><p>待付款锁定库存，取消释放；采购收货入库，整箱直发不增加商城库存。</p></article><article><h3>收益与退款</h3><p>完成订单才能提现。退款沿原快照冲正，同级分红支出由商城拥有者承担。</p></article></div></template>
<el-result v-else-if="module==='overview'" icon="warning" title="经营数据不可访问" :sub-title="error"><template #extra><el-button @click="load">重试读取</el-button></template></el-result>
 <el-result v-else-if="error&&module!=='applications'" icon="warning" title="业务数据不可访问" :sub-title="error"><template #extra><el-button @click="load">重试读取</el-button></template></el-result>
 <section v-else class="hx-section"><div v-if="module==='agents'&&!error" class="hx-agent-guide"><div><strong>查看代理上下级与经营区域</strong><p>选择商城后点“打开关系明细”；左侧展开下级，右侧查看当前代理的上级、直接下级名单和区域。</p></div><el-button type="primary" @click="openAgentTree()">打开关系明细</el-button></div><el-tabs v-if="visibleTabs.length" v-model="activeTab" :before-leave="() => !saving&&!uploading" @tab-change="handleTabChange"><el-tab-pane v-for="t in visibleTabs" :key="t[1]" :label="t[0]" :name="t[1]"/></el-tabs><el-result v-if="error" icon="warning" title="当前页签不可访问" :sub-title="error"><template #extra><el-button @click="load">重试读取</el-button></template></el-result><template v-else><div class="hx-toolbar"><el-input v-model="search" placeholder="搜索当前列表中的编号、名称或状态" clearable style="max-width:360px"/><div><el-button v-if="activeTab==='resources/staff'" type="primary" @click="editStaff()">分配商城岗位</el-button><el-button v-if="module==='settings'" @click="editMarketing">营销金额试算</el-button><el-button v-if="module==='products'" type="primary" @click="editProduct()">新增商品</el-button><el-button v-if="module==='settings'&&activeTab.startsWith('documents/')||module==='settings'&&activeTab==='rules'" type="primary" @click="editSetting()">{{activeTab==='rules'?'新建分红版本':'新增配置'}}</el-button><el-button v-if="activeTab==='documents/shop_transfer'" type="primary" @click="editSetting()">申请商城交接</el-button><el-button v-if="activeTab==='documents/team_migration'" type="primary" @click="newMigration">生成团队迁移名单</el-button><el-button v-if="activeTab==='resources/assessmentPeriods'||activeTab==='documents/downgrade'" @click="runAssessment">核算已结束周期</el-button><el-button v-if="activeTab==='resources/reconciliationLines'&&statementBatch" @click="statementBatch='';load()">显示最近明细</el-button><el-button v-if="activeTab==='resources/reconciliationBatches'" type="primary" @click="newStatement">导入账单</el-button><el-button v-if="activeTab==='backups'" type="primary" @click="backupNow">立即加密备份</el-button><el-button @click="exportRows">导出当前数据</el-button></div></div><el-table :data="filteredRows" stripe border empty-text="暂无业务数据，新的申请和交易会在此同步" :row-key="row=>row.id??row.user_id??(row.campaign_id?row.campaign_id+':'+(row.order_id||'')+':'+(row.agent_id||row.recipient_agent_id||'')+':'+(row.reward_type||''):row.member_id)"><el-table-column v-for="col in tableColumns" :key="col[0]" :prop="col[0]" :label="col[1]" :min-width="columnMinWidth(col[0])" :width="module==='products'&&col[0]==='status'?100:undefined" :fixed="module==='products'&&col[0]==='status'?'right':false" :show-overflow-tooltip="!wrapListKey(col[0])" :class-name="wrapListKey(col[0])?'hx-wrap-id':''"><template #default="{row}"><el-tag v-if="col[0]==='status'" :type="earningFullyReversed(row)?'info':['REJECTED','FAILED'].includes(row.status)?'danger':['PENDING','UNPAID','WAIT_RETURN'].includes(row.status)?'warning':'success'">{{workspaceStatusCell(row,module,labels)}}</el-tag><span v-else-if="col[2]==='money'">{{row[col[0]]==null?'—':formatCurrency(row[col[0]])}}</span><div v-else-if="activeTab==='resources/pointTransfers'&&viewportWidth<=600&&col[0]==='reference_id'" class="hx-transfer-mobile"><strong>{{row.reference_id}}</strong><span>转出：{{row.sender_name||'—'}}</span><span>接收：{{row.recipient_name||'—'}}</span><span>转出 {{row.amount}} · 到账 {{row.credit}} 积分</span><span>{{workspaceListCell('created_at',row.created_at)}}</span></div><span v-else-if="col[0]==='rank_no'">{{workspaceRankCell(row.rank_no)}}</span><span v-else>{{workspaceListCell(col[0],row[col[0]],labels)}}</span></template></el-table-column><el-table-column label="操作" fixed="right" :width="actionColumnWidth"><template #default="{row}"><el-button link type="primary" @click="showDetail(row)">详情</el-button><el-button v-if="module==='agents'&&activeTab==='resources/agents'" link type="primary" @click="openAgentTree(row)">上下级</el-button><el-button v-if="module==='finance'&&activeTab==='resources/withdrawals'&&row.channel==='BANK'&&['APPROVED','PROCESSING'].includes(row.status)" link type="primary" :disabled="saving" @click="openBankPayout(row)">登记打款结果</el-button><el-button v-if="module==='finance'&&activeTab==='resources/withdrawals'&&row.channel&&row.channel!=='BANK'&&row.status==='APPROVED'" link type="primary" :disabled="saving" @click="submitChannelPayout(row)">发起渠道打款</el-button><el-button v-if="activeTab==='resources/reconciliationBatches'" link type="primary" @click="showStatement(row)">查看明细</el-button><template v-if="module==='products'"><el-button link type="primary" @click="editProduct(row)">编辑</el-button><el-button link @click="stock(row)">调库存</el-button><el-button link @click="editBox(row)">箱规混批</el-button><el-button link @click="toggleSku(row)">{{row.status==='ACTIVE'?'下架':'审核上架'}}</el-button></template><el-button v-if="activeTab==='resources/staff'" link type="primary" @click="editStaff(row)">调整岗位</el-button><el-button v-if="activeTab==='resources/pointRiskCases'&&['PENDING','RETAINED'].includes(row.status)" link type="primary" @click="open('pointReview',row)">冻结复核</el-button><el-button v-if="module==='orders'&&row.status==='PAID'&&(!row.group||row.group.status==='FORMED')" link type="primary" @click="open('ship',row)">发货</el-button><el-button v-if="(module==='refunds'||module==='applications'||module==='finance'&&['resources/withdrawals','resources/reconciliationAdjustments'].includes(activeTab))&&['PENDING','SUPPLEMENT','REVIEW_REQUIRED'].includes(row.status)" link type="primary" @click="open('review',row)">审核</el-button><el-button v-if="module==='refunds'&&row.status==='WAIT_EXCHANGE'" link type="primary" @click="open('exchange',row)">换货发货</el-button><el-button v-if="module==='refunds'&&row.status==='WAIT_RETURN'" link type="primary" @click="open('inspect',row)">验收</el-button><el-button v-if="module==='refunds'&&row.status==='APPROVED'&&Number(row.amount)>0" link type="primary" :disabled="saving" @click="submitChannelRefund(row)">发起原路退款</el-button><el-button v-if="activeTab==='resources/channelEvents'&&row.status==='ERROR'" link type="primary" @click="retryChannel(row)">重试处理</el-button><el-button v-if="activeTab==='resources/reconciliationLines'&&!['RESOLVED','PENDING'].includes(row.status)" link @click="recheckLine(row)">重新核对</el-button><el-button v-if="activeTab==='resources/reconciliationLines'&&row.status==='AMOUNT_MISMATCH'" link type="primary" @click="open('adjustment',row)">申请调整</el-button><el-button v-if="module==='settings'&&activeTab.startsWith('documents/')&&row.status==='ACTIVE'" link type="primary" @click="editSetting(row)">编辑</el-button></template></el-table-column></el-table><div class="hx-table-foot"><span>共 {{filteredRows.length}} 条 · {{activeTab==='backups'?'平台备份任务':'当前商城数据'}}</span><span>{{activeTab==='backups'?'加密文件与密钥须分别安全保管':module==='refunds'?'现金金额按元显示，积分以积分为单位':module==='settings'?'配置按当前商城隔离':'金额单位已换算为元，原始账务以分记账'}}</span></div></template></section>
  <el-drawer :key="detailRequest" v-model="drawer" title="业务记录详情" size="min(720px, 95vw)">
    <div v-if="workflowDetail&&selectedUploads.length" class="hx-attachments"><el-button v-for="(id,i) in selectedUploads" :key="id" @click="viewAttachment(id)">查看资料 {{i+1}}</el-button></div>
    <ReviewDocumentDetail v-if="reviewDetail" :record="selected"/>
    <WorkflowDocumentDetail v-else-if="workflowDetail" :record="selected"/>
    <template v-else>
    <template v-if="module==='orders'">
      <el-alert v-if="trackingError" :title="trackingError" type="warning" :closable="false" class="hx-tracking"/>
      <div v-else-if="tracking" class="hx-tracking">
        <h3>物流轨迹</h3>
        <p>{{tracking.carrier||'承运商待确认'}} · {{tracking.tracking||'暂无运单号'}} · {{tracking.status==='UNAVAILABLE'?'承运商接口未配置':tracking.status||'待更新'}}</p>
        <el-timeline v-if="tracking.events?.length"><el-timeline-item v-for="(event,i) in tracking.events" :key="i" :timestamp="event.time">{{event.description}}</el-timeline-item></el-timeline>
        <el-empty v-else description="暂无真实物流轨迹" :image-size="60"/>
      </div>
    </template>
    <MemberProfile v-if="drawer&&module==='agents'&&selected.member_id" :key="shopId+':'+selected.member_id" :member-id="selected.member_id" :shop-id="shopId"/>
    <div v-if="selectedUploads.length" style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:16px"><el-button v-for="(id,i) in selectedUploads" :key="id" @click="viewAttachment(id)">{{activeTab==='resources/reconciliationAdjustments'?'查看财务凭证':'查看资料'}} {{i+1}}</el-button></div>
    <OrderItemsPreview v-if="drawer&&module==='orders'" :items="selected.items"/>
    <el-descriptions :column="1" :label-width="128" border>
      <el-descriptions-item v-for="(value,key) in detailRecord" :key="key" :label="fieldLabel(key)">
        <pre v-if="structuredField(key,value)">{{JSON.stringify(value,null,2)}}</pre>
        <span v-else :style="activeTab==='documents/support'&&key==='message'?{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}:{}">{{fieldValue(key,value)}}</span>
        <ProductImagePreview v-if="module==='products'&&key==='asset'" :asset="value"/>
      </el-descriptions-item>
    </el-descriptions>
    </template>
    <template v-if="module==='applications'&&['PENDING','SUPPLEMENT','REVIEW_REQUIRED'].includes(selected.status)||module==='settings'&&selected.status==='ACTIVE'&&activeTab==='documents/system_parameter'" #footer>
      <el-button v-if="module==='applications'" type="primary" @click="drawer=false;open('review',selected)">{{activeTab==='documents/support'?'回复这条留言':'审核这条申请'}}</el-button>
      <el-button v-else type="primary" @click="drawer=false;editSetting(selected)">编辑此配置</el-button>
    </template>
  </el-drawer>
  <el-dialog v-model="imageDialog" :title="activeTab==='resources/reconciliationAdjustments'?'财务凭证':'已授权的业务资料'" width="min(850px,95vw)" @closed="closeAttachment"><img :src="attachmentUrl" :alt="activeTab==='resources/reconciliationAdjustments'?'财务凭证图片':'业务申请附件'" style="max-width:100%;max-height:75vh;display:block;margin:auto"/></el-dialog>
  <el-dialog v-model="agentTreeOpen" title="代理上下级与经营区域明细" width="min(1440px,96vw)" top="3vh" class="agent-tree-dialog" destroy-on-close>
    <AgentTree v-if="agentTreeOpen" :key="shopId+':'+agentTreeRoot" :shop-id="shopId" :initial-agent-id="agentTreeRoot" :can-edit="canEditAgentRegion"/>
  </el-dialog>
  <el-dialog v-model="dialog" :show-close="!saving&&!uploading" :close-on-press-escape="!saving&&!uploading" :title="dialogTitle" width="min(620px, 95vw)" :close-on-click-modal="false"><el-form :key="dialog?mode+':'+(form.id||'new'):'closed'" label-position="top" :disabled="saving||uploading" @submit.prevent="submit"><template v-if="mode==='staff'"><el-form-item label="已有后台登录账号" required><el-input v-model="form.userName" @input="form.userId=0"/><el-button @click="lookupStaff">核对账号</el-button></el-form-item><el-alert v-if="form.userId" :title="'已核对：'+form.nickName+' · '+form.userId" :closable="false"/><el-form-item label="商城岗位"><el-select v-model="form.role"><el-option v-for="(value,key) in staffRoles" :key="value" :label="key" :value="value"/></el-select></el-form-item><el-form-item label="启用本商城岗位"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="变更原因" required><el-input v-model="form.reason" type="textarea"/></el-form-item><el-alert title="停用仅撤销当前商城权限。平台管理员和全局账号状态由平台账号管理维护。" :closable="false"/></template><template v-else-if="mode==='marketing'"><el-form-item label="当前商城客户编号"><el-input-number v-model="form.customerId" :min="1" :precision="0"/></el-form-item><el-form-item label="商品编号"><el-input v-model="form.skuId"/></el-form-item><el-form-item label="购买数量"><el-input-number v-model="form.qty" :min="1" :precision="0"/></el-form-item><el-form-item label="抵扣平台积分"><el-input-number v-model="form.points" :min="0" :precision="0"/></el-form-item><el-form-item label="客户优惠券编号（选填）"><el-input v-model="form.couponId"/></el-form-item><el-form-item label="收货地区"><el-input v-model="form.region"/></el-form-item><el-descriptions v-if="form.result" :column="2" border><el-descriptions-item v-for="(title,key) in {subtotal:'商品金额',promotionDiscount:'活动优惠',couponDiscount:'优惠券',pointsDiscount:'积分抵扣',freight:'运费',total:'最终应付',cost:'职级成本',margin:'价差毛利'}" :key="key" :label="title">¥{{money(form.result[key])}}</el-descriptions-item></el-descriptions><el-alert title="按客户真实身份和当前业务规则只读试算；不创建订单、不占用库存或积分。" :closable="false"/></template><template v-else-if="mode==='statement'"><el-form-item label="账单日期" required><el-date-picker v-model="form.statementDate" type="date" value-format="YYYY-MM-DD"/></el-form-item><el-form-item label="账单明细 CSV 文件" required><input type="file" accept=".csv,text/csv" @change="readStatementFile"/></el-form-item><el-button @click="statementTemplate">下载导入模板</el-button><el-alert title="按模板填写支付、退款或提现的业务单号、渠道流水、商户号及金额（整数分）。每批最多5000条。" :closable="false"/><el-table v-if="form.rows.length" :data="form.rows.slice(0,5)"><el-table-column prop="type" label="类型"/><el-table-column prop="businessId" label="业务单号"/><el-table-column prop="amount" label="金额（分）"/></el-table><p>已读取 {{form.rows.length}} 条明细</p><el-alert title="人工导入仅核对所提供明细，不能证明渠道真实性，也不会将未支付订单改为已支付。" type="warning" :closable="false"/></template><template v-else-if="mode==='adjustment'"><el-descriptions :column="1" border><el-descriptions-item label="业务单号">{{selected.business_id}}</el-descriptions-item><el-descriptions-item label="拟调整金额">¥{{money(selected.difference)}}</el-descriptions-item></el-descriptions><el-form-item label="调整原因" required><el-input v-model="form.reason" type="textarea" :maxlength="500"/></el-form-item><el-form-item label="财务凭证（1至9张图片）" required><el-upload accept="image/png,image/jpeg" :http-request="uploadProof" :limit="9" :disabled="uploading" :on-remove="removeProof"><el-button :loading="uploading">上传凭证</el-button></el-upload></el-form-item><el-alert title="须由另一位有财务权限的人员复核。通过后新增调整流水，保留原订单和支付记录。" :closable="false"/></template><template v-else-if="mode==='product'||mode==='box'"><div class="hx-form-grid"><el-form-item v-for="f in (mode==='box'?boxFields:productFields)" :key="f[0]" :label="f[1]"><el-input-number v-if="f[2]==='number'" v-model="form[f[0]]" :min="0" :precision="0" controls-position="right"/><el-switch v-else-if="f[2]==='switch'" v-model="form[f[0]]"/><el-input v-else v-model="form[f[0]]" :type="f[2]==='textarea'?'textarea':'text'" :disabled="(f[0]==='id'&&editing)||f[0]==='asset'"/></el-form-item></div><template v-if="mode==='product'"><ProductImagePreview :asset="form.asset"/><el-form-item label="商品图库（最多9张）"><el-upload accept="image/png,image/jpeg" :http-request="uploadProduct" :disabled="uploading" :show-file-list="false"><el-button :loading="uploading">上传商品图片</el-button></el-upload></el-form-item><el-tag v-for="(file,i) in form.gallery||[]" :key="file" closable @close="form.gallery.splice(i,1);if(form.asset===file)form.asset=form.gallery[0]||''" @click="viewAttachment(file)">图片 {{i+1}}</el-tag></template></template><template v-else-if="mode==='stock'"><el-form-item label="调整数量（负数为出库）"><el-input-number v-model="form.quantity" :precision="0"/></el-form-item><el-form-item label="调整原因" required><el-input v-model="form.reason" type="textarea"/></el-form-item></template><template v-else-if="mode==='migration'"><el-form-item label="团队根代理编号"><el-input-number v-model="form.rootAgentId" :min="1" :precision="0"/></el-form-item><el-form-item label="目标商城"><el-select v-model="form.targetShopId"><el-option v-for="s in shops.filter(s=>s.id!==shopId)" :key="s.id" :label="s.name" :value="s.id"/></el-select></el-form-item><el-form-item label="迁移生效时间"><el-date-picker v-model="form.effectiveAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-alert title="先生成完整代理和客户名单，再由平台审核。历史订单和账本保持原商城归属。" :closable="false"/></template><template v-else-if="['ship','exchange'].includes(mode)"><el-form-item label="快递公司"><el-select v-model="form.carrier"><el-option v-for="s in ['顺丰速运','中通快递','圆通速递','韵达快递']" :key="s" :value="s"/></el-select></el-form-item><el-form-item label="快递单号" required><el-input v-model="form.tracking"/></el-form-item></template><template v-else-if="mode==='pointReview'"><el-form-item label="处理结果"><el-radio-group v-model="form.release"><el-radio :value="true">解除冻结</el-radio><el-radio :value="false">继续冻结</el-radio></el-radio-group></el-form-item><el-form-item label="复核依据" required><el-input v-model="form.reason" type="textarea"/></el-form-item><el-alert title="解冻不清零日累计和频率计数；解除后原积分余额保持不变。" :closable="false"/></template><template v-else-if="mode==='review'"><el-form-item label="审核结果"><el-radio-group v-if="contentReview" v-model="form.decision"><el-radio value="APPROVED">通过</el-radio><el-radio value="REJECTED">驳回</el-radio><el-radio value="SUPPLEMENT">待补充资料</el-radio></el-radio-group><el-radio-group v-else v-model="form.approve"><el-radio :value="true">通过</el-radio><el-radio :value="false">驳回</el-radio></el-radio-group></el-form-item><el-form-item v-if="activeTab==='documents/agent_application'&&form.approve" label="经营区域（可在关系树补录）"><el-select v-model="form.regions" multiple filterable remote :multiple-limit="10" :remote-method="searchReviewRegions" :loading="reviewRegionLoading" placeholder="输入至少两个字搜索地区" style="width:100%"><el-option v-for="area in reviewRegionOptions" :key="area" :label="area" :value="area"/></el-select></el-form-item><el-form-item v-if="activeTab==='documents/downgrade'" label="生效时间（留空为立即，审核时复核实际订单与商城处置）"><el-date-picker v-model="form.effectiveAt" type="datetime" value-format="YYYY-MM-DD HH:mm:ss"/></el-form-item><el-form-item :label="activeTab==='documents/support'?'回复内容':contentReview?'审核意见 / 驳回或补充原因':'审核意见 / 驳回原因'" :required="activeTab==='documents/support'||contentReview&&form.decision!=='APPROVED'"><el-input v-model="form.reason" type="textarea" :rows="3"/></el-form-item><el-checkbox v-if="activeTab==='documents/shop_transfer'" v-model="form.handoverConfirmed">已核对完整交接清单、库存、资金和商户授权处置</el-checkbox><el-checkbox v-if="activeTab==='documents/promotion'" v-model="form.assessmentVerified">已核实真实订单与考核指标达标</el-checkbox><el-alert v-if="module==='finance'" :title="activeTab==='resources/reconciliationAdjustments'?'复核通过将新增独立调整流水，申请人不能自审。':'通过后仍需付款渠道处理，不会直接标记到账。'" type="info" :closable="false"/></template><template v-else-if="mode==='inspect'"><el-form-item label="实际收到数量"><el-input-number v-model="form.receivedQty" :min="0" :precision="0"/></el-for