let reviewRegionRequest=0
async function searchReviewRegions(value){
 if(String(value||'').trim().length<2)return
 const requestId=++reviewRegionRequest
 reviewRegionLoading.value=true
 try{const response=await agentRegionOptions(shopId.value,value);if(requestId===reviewRegionRequest)reviewRegionOptions.value=response.data}
 catch(e){if(requestId===reviewRegionRequest)ElMessage.error(e.message||'地区查询失败')}
 finally{if(requestId===reviewRegionRequest)reviewRegionLoading.value=false}
}
const canEditAgentRegion=computed(()=>{const shop=shops.value.find(item=>Number(item.id)===Number(shopId.value));return !!shop&&(!shop.role_code||shop.role_code==='OWNER')})
function openAgentTree(row){agentTreeRoot.value=Number(row?.id)||0;agentTreeOpen.value=true}
const tabs=workspaceTabs(props.module,config.tabs,backupEnabled)
const shopId=ref(Number(route.query.shopId)||2),shops=ref([]),rows=ref([]),recentOrders=ref([]),summary=ref({}),search=ref(props.module==='refunds'?String(route.query.refundId||''):''),loading=ref(false),error=ref(''),activeTab=ref(tabs[0]?.[1]||''),drawer=ref(false),selected=ref({}),dialog=ref(false),mode=ref(''),form=ref({}),saving=ref(false),editing=ref(false)
watch(shopId,()=>{agentTreeOpen.value=false;agentTreeRoot.value=0})
const visibleTabs=computed(()=>{
 if(props.module!=='applications')return tabs
 const shop=shops.value.find(shop=>Number(shop.id)===Number(shopId.value))
 if(!shop)return []
 const role=shop.role_code
 if(!role||role==='OWNER')return config.tabs
 const allowed={SUPPORT:['support','review','review_append'],WAREHOUSE:['stocktake'],FINANCE:['settlement_account']}[role]||[]
 return config.tabs.filter(([,path])=>allowed.includes(path.slice('documents/'.length)))
})
