const compactViewport=computed(()=>viewportWidth.value<=(props.module==='finance'||props.module==='audit'&&activeTab.value==='resources/inventory'?1500:1100))
const compactColumnKeys=computed(()=>{
 if(!compactViewport.value)return null
 if(props.module==='orders')return ['id','order_type','total','status','created_at']
 if(props.module==='refunds')return ['id','refund_type','refund_display','status']
 if(props.module==='applications')return ['id','member_id','status','created_at']
 if(props.module==='finance'&&activeTab.value==='resources/withdrawals')return ['id','member_id','amount','net','status']
 if(props.module==='finance'&&activeTab.value==='resources/reconciliationAdjustments')return ['id','business_id','amount','status','reviewed_by']
 if(props.module==='audit'&&activeTab.value==='resources/audit')return ['id','actorName','action','reference_id','created_at']
 if(props.module==='audit'&&activeTab.value==='resources/inventory')return ['id','sku_id','available_delta','locked_delta','defective_delta','created_at']
 if(props.module==='settings'&&activeTab.value.startsWith('documents/'))return ['id','title','status','updated_at']
 return null
})
const tableColumns=computed(()=>activeTab.value==='resources/pointTransfers'&&viewportWidth.value<=600?columns.value.filter(col=>col[0]==='reference_id'):compactColumnKeys.value?columns.value.filter(col=>compactColumnKeys.value.includes(col[0])):columns.value)
