// 商品名称允许换行；窄屏列表中的其他编号仍按原规则显示。
const wrapListKey=key=>props.module==='products'&&key==='name'||activeTab.value==='resources/pointTransfers'&&['reference_id','sender_name','recipient_name','created_at'].includes(key)||!!compactColumnKeys.value&&(['id','order_id','business_id'].includes(key)||(props.module==='audit'&&['actorName','action','reference_id','sku_id'].includes(key))||(props.module==='settings'&&activeTab.value==='documents/coupon'&&key==='title'))
