const metrics=computed(()=>[{label:'有效销售额',value:'¥'+money(summary.value.sales),note:'扣除已退款金额'},{label:'订单总数',value:summary.value.orders||0,note:'包含各业务状态'},{label:'待发货订单',value:summary.value.pendingShip||0,note:'已付款，待履约'},{label:'库存预警',value:summary.value.stockWarnings||0,note:'低于SKU预警阈值'}])
