const permissionDenied=message=>/无此操作权限|没有.*权限|无权/.test(message||'')
async function load(findAccessible=false){
 clearTimeout(refreshTimer)
 if(shopId.value===0&&!platformPointPaths.includes(activeTab.value))shopId.value=shops.value[0]?.id
 if(props.module==='applications'&&!visibleTabs.value.some(([,path])=>path===activeTab.value))activeTab.value=visibleTabs.value[0]?.[1]||''
 if(props.module==='applications'&&!activeTab.value){loadRequest++;detailRequest++;drawer.value=false;dialog.value=false;selected.value={};rows.value=[];loading.value=false;error.value='当前岗位没有可审核的业务';return}
 const requestId=++loadRequest,scope=shopId.value,tab=activeTab.value,batch=statementBatch.value
  // 每次刷新均使旧详情失效；撤岗后的 403 或迟到响应不得继续展示敏感记录。
  detailRequest++;drawer.value=false;dialog.value=false;selected.value={};form.value={};tracking.value=null;trackingError.value='';imageDialog.value=false;closeAttachment()
 lastScope=scope;lastTab=tab;rows.value=[];recentOrders.value=[];summary.value={}
 loading.value=true;error.value=''
 try{
  if(scope==null&&tab!=='backups')throw new Error('当前账号没有可管理的商城')
  if(props.module==='overview'){
   const d=await query('dashboard',scope)
   const o=await query('orders',scope)
   if(requestId===loadRequest){summary.value=d.data;recentOrders.value=(o.data||[]).slice(0,8)}
  }else{
   const path=tab==='resources/reconciliationLines'&&batch?'statements/'+encodeURIComponent(batch)+'/lines':tab||config.path
   const response=await query(path,scope)
   if(requestId===loadRequest)rows.value=(response.data||[]).map(x=>workspaceListRow(x,path))
  }
 }catch(e){
  if(requestId!==loadRequest)return
  error.value=e.message||'数据读取失败，请稍后重试'
  if(findAccessible===true&&props.module==='applications'&&permissionDenied(error.value)){
   const candidates=visibleTabs.value.map(([,path])=>path).filter(path=>path!==tab)
   for(const candidate of candidates){
    try{
     const response=await query(candidate,scope)
     if(requestId!==loadRequest||scope!==shopId.value)return
     selectingAccessibleTab=true;activeTab.value=candidate
     await nextTick()
     selectingAccessibleTab=false
     rows.value=(response.data||[]).map(x=>workspaceListRow(x,candidate))
     error.value=''
     break
    }catch(nextError){
     if(requestId!==loadRequest)return
     if(!permissionDenied(nextError.message)){error.value=nextError.message||'数据读取失败，请稍后重试';break}
    }
   }
  }
 }
 finally{if(requestId===loadRequest){loading.value=false;if(tab==='resources/reconciliationBatches'&&rows.value.some(r=>['QUEUED','PROCESSING'].includes(r.status)))refreshTimer=setTimeout(load,5000)}}
}
