async function submit(){if(saving.value||uploading.value)return;saving.value=true;let remoteCommandStarted=false;try{const actionError=workspaceActionError(mode.value,form.value,{tab:activeTab.value,selected:selected.value,shopId:shopId.value});if(actionError)throw new Error(actionError);if(mode.value==='marketing'){if(!Number.isInteger(Number(form.value.customerId))||Number(form.value.customerId)<1||!String(form.value.skuId||'').trim()||!Number.isInteger(Number(form.value.qty))||Number(form.value.qty)<1)throw new Error('请填写客户编号、商品编号和购买数量');form.value.result=null;remoteCommandStarted=true;form.value.result=(await command('marketing-preview',{shopId:shopId.value,customerId:form.value.customerId,items:[{id:form.value.skuId,qty:form.value.qty}],points:form.value.points,couponId:form.value.couponId,address:{name:'金额试算',region:form.value.region,detail:'不创建订单'}})).data;return;}if(form.value.bankPayout){const data=bankPayoutPayload(shopId.value,selected.value,form.value),validation=bankPayoutError(data);if(validation)throw new Error(validation);remoteCommandStarted=true;await bankPayoutResult(data);ElMessage.success('银行卡打款结果已登记');dialog.value=false;await load();return;}if(mode.value==='staff'&&!form.value.userId)throw new Error('请先核对后台账号');if(mode.value==='product'){if(!/^[A-Za-z0-9_-]{1,64}$/.test(String(form.value.id||''))||!String(form.value.name||'').trim())throw new Error('请填写有效商品编号和名称');const prices=[form.value.retail,form.value.cloud_price,form.value.center_price,form.value.owner_price].map(Number);if(prices.some(value=>!Number.isInteger(value)||value<=0)||!(prices[0]>=prices[1]&&prices[1]>=prices[2]&&prices[2]>=prices[3]))throw new Error('价格须为正整数且零售≥云价≥中心价≥总代价');if([form.value.weight_grams,form.value.box_size,form.value.min_boxes,form.value.min_qty].some(value=>!Number.isInteger(Number(value))||Number(value)<=0))throw new Error('重量、箱规和起订量须为正整数')}if(mode.value==='box'&&[form.value.box_size,form.value.min_boxes,form.value.min_qty,form.value.mix_units].some(value=>!Number.isInteger(Number(value))||Number(value)<=0))throw new Error('箱规、起订量和箱容积分须为正整数');if(mode.value==='staff'&&String(form.value.reason||'').trim().length<2)throw new Error('请填写岗位变更原因');if(mode.value==='stock'&&(Number(form.value.quantity||0)===0||String(form.value.reason||'').trim().length<2))throw new Error('库存调整数量不能为零且须填写原因');if(['ship','exchange'].includes(mode.value)&&!/^[A-Za-z0-9]{8,40}$/.test(String(form.value.tracking||'').trim()))throw new Error('请填写8至40位字母或数字运单号');if(mode.value==='pointReview'&&String(form.value.reason||'').trim().length<2)throw new Error('请填写冻结复核依据');if(mode.value==='review'&&!contentReview.value&&!form.value.approve&&!String(form.value.reason||'').trim())throw new Error('驳回必须填写原因');if(mode.value==='review'&&form.value.approve&&activeTab.value==='documents/shop_transfer'&&!form.value.handoverConfirmed)throw new Error('请先确认完整交接清单');if(mode.value==='review'&&form.value.approve&&activeTab.value==='documents/promotion'&&!form.value.assessmentVerified)throw new Error('请先确认考核资料已核实');if(mode.value==='review'&&form.value.approve&&['documents/shop_transfer','documents/downgrade'].includes(activeTab.value)&&String(form.value.reason||'').trim().length<2)throw new Error('请填写审核意见');let op={staff:'staff-assign',statement:'reconcile-import',adjustment:'adjustment-propose',pointReview:'point-freeze-review',box:'sku-box-rules',product:'sku-save',stock:'stock-adjust',exchange:'exchange-ship',ship:'ship',inspect:'return-inspect',rule:'rule-create',setting:'document-save'}[mode.value];let data={...form.value,shopId:shopId.value};if(mode.value==='review'){op=props.module==='refunds'?'refund-review':props.module==='finance'?(activeTab.value==='resources/reconciliationAdjustments'?'adjustment-review':'withdraw-review'):'document-review';data={...workspaceReviewPayload(form.value,activeTab.value),shopId:shopId.value}}if(mode.value==='statement'&&(!data.statementDate||!data.rows.length))throw new Error('请填写账单日期并上传明细文件');if(mode.value==='setting'){data.kind=activeTab.value.replace('documents/','');for(const f of currentFields.value)if(f[2]==='json'){try{const fallback=['assets','screens'].includes(f[0])?'{}':'[]';data[f[0]]=JSON.parse(data[f[0]]||fallback);const jsonError=settingJsonError(f[0],data[f[0]]);if(jsonError)throw new Error(jsonError)}catch{throw new Error(f[1]+'格式错误')}}}remoteCommandStarted=true;if(mode.value==='migration')await agencyCommand('team-migration',data);else if(mode.value==='review'&&activeTab.value==='documents/team_migration')await agencyCommand('team-migration/'+data.id+'/review',data);else await command(op,data);ElMessage.success('操作成功，数据已保存');dialog.value=false;await load()}catch(e){if(!remoteCommandStarted||e.message==='登录账号已变化，请在当前账号重新确认操作')ElMessage.error(e.message||'操作失败')}finally{saving.value=false}}

async function showStatement(row){statementBatch.value=row.id;activeTab.value='resources/reconciliationLines';await load()}
function newStatement(){mode.value='statement';form.value={statementDate:new Date().toISOString().slice(0,10),rows:[]};dialog.value=true}
function statementTemplate(){const csv='\ufeff业务类型,业务单号,渠道流水,商户号,金额（分）\r\n';const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='对账导入模板.csv';a.click();URL.revokeObjectURL(url)}
async function readStatementFile(event){form.value.rows=[];try{const f=event.target.files?.[0];if(!f)return;if(f.size>2*1024*1024)throw new Error('账单文件不能超过2MB');const source=(await f.text()).replace(/^\ufeff/,'');const result=[];let row=[],field='',quoted=false;for(let i=0;i<source.length;i++){const c=source[i];if(c==='"'){if(quoted&&source[i+1]==='"'){field+='"';i++}else quoted=!quoted}else if(c===','&&!quoted){row.push(field);field=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&source[i+1]==='\n')i++;row.push(field);if(row.some(x=>x.trim()))result.push(row);row=[];field=''}else field+=c}if(quoted)throw new Error('CSV引号不完整');row.push(field);if(row.some(x=>x.trim()))result.push(row);const header=result.shift()?.map(x=>x.trim());if(header?.join(',')!=='业务类型,业务单号,渠道流水,商户号,金额（分）')throw new Error('请使用导入模板中的列名和顺序');if(!result.length||result.length>5000)throw new Error('每批须为1至5000条');form.value.rows=result.map((r,i)=>{if(r.length!==5||!/^\d+$/.test(r[4].trim())||!Number.isSafeInteger(Number(r[4])))throw new Error('第'+(i+2)+'行字段或金额格式错误');const type=({'支付':'PAYMENT','退款':'REFUND','提现':'PAYOUT'}[r[0].trim()]||r[0].trim());if(!['PAYMENT','REFUND','PAYOUT'].includes(type)||r.slice(1,4).some(x=>!x.trim()))throw new Error('第'+(i+2)+'行业务信息不完整');return {type,businessId:r[1].trim(),channelRef:r[2].trim(),merchantNo:r[3].trim(),amount:Number(r[4])}})}catch(e){ElMessage.error(e.message)}}
async function uploadProof(options){const validation=imageUploadError(options.file)||(mode.value==='setting'&&activeTab.value==='documents/decoration'?decorationUploadError(form.value):'');if(validation||uploading.value){const error=new Error(validation||'图片正在上传，请稍后再试');ElMessage.error(error.message);options.onError?.(error);return}uploading.value=true;try{const purpose=mode.value==='inspect'?'RETURN':mode.value==='setting'&&activeTab.value==='documents/link_campaign'?'LINK_CONFIRMATION':mode.value==='setting'&&activeTab.value==='documents/decoration'?'STOREFRONT':'FINANCE';const response=await uploadFinance(options.file,shopId.value,purpose);form.value.uploads=[...(form.value.uploads||[]),response.data.id];if(mode.value==='setting'&&activeTab.value==='documents/decoration'){form.value.asset=response.data.id;try{const parsed=JSON.parse(form.value.assets||'{}');const assets=parsed&&typeof parsed==='object'&&!Array.isArray(parsed)?parsed:{};assets.uploaded=response.data.id;form.value.assets=JSON.stringify(assets,null,2)}catch{form.value.assets=JSON.stringify({uploaded:response.data.id},null,2)}try{const banners=JSON.parse(form.value.banners||'[]');if(Array.isArray(banners)&&banners[0]){banners[0].image=response.data.id;form.value.banners=JSON.stringify(banners,null,2)}}catch{}}else if(mode.value==='setting')form.value.confirmationFile=response.data.id;options.onSuccess(response.data);return response.data}catch(e){ElMessage.error(e.message||'图片上传失败');options.onError?.(e)}finally{uploading.value=false}}
function removeProof(file){
 const id=file.response?.id;if(!id)return
 form.value.uploads=(form.value.uploads||[]).filter(item=>item!==id)
 if(form.value.confirmationFile===id)form.value.confirmationFile=''
 if(activeTab.value==='documents/decoration')form.value=removeDecorationAttachment(form.value,id)
}
async function recheckLine(row){if(saving.value)return;saving.value=true;try{await command('reconcile-recheck',{shopId:shopId.value,id:row.id});ElMessage.success('已按最新业务及回执核对');await load()}catch(e){ElMessage.error(e.message||'重新核对失败')}finally{saving.value=false}}

async function viewAttachment(id){const current=attachmentGate.begin();try{const blob=await attachment(id);if(!current())return;if(!blob.type.startsWith('image/')){const response=JSON.parse(await blob.text());if(!current())return;throw new Error(response.msg||'资料读取失败')}clearAttachmentUrl();attachmentUrl.value=URL.createObjectURL(blob);imageDialog.value=true}catch(e){if(current())ElMessage.error(e.message)}}
function clearAttachmentUrl(){if(attachmentUrl.value)URL.revokeObjectURL(attachmentUrl.value);attachmentUrl.value=''}
function closeAttachment(){attachmentGate.invalidate();clearAttachmentUrl()}
function newMigration(){mode.value='migration';form.value={rootAgentId:0,targetShopId:null,effectiveAt:''};dialog.value=true}
async function toggleSku(row){
 if(saving.value)return
 saving.value=true
 try{
  try{await ElMessageBox.confirm(row.status==='ACTIVE'?'确认下架该商品？':'确认审核通过并上架该商品？','商品状态')}catch{return}
  await command('sku-status',{shopId:shopId.value,id:row.id,status:row.status==='ACTIVE'?'INACTIVE':'ACTIVE'})
  ElMessage.success('商品状态已更新');await load()
 }catch(e){ElMessage.error(e.message||'商品状态更新失败')}finally{saving.value=false}
}
async function backupNow(){if(saving.value)return;saving.value=true;try{await startBackup();ElMessage.success('备份任务已启动，可刷新查看结果');await load()}catch(e){ElMessage.error(e.message||'备份启动失败')}finally{saving.value=false}}
async function retryChannel(row){if(saving.value)return;saving.value=true;try{await channelRetry(row.id);ElMessage.success('回执已处理');await load()}catch(e){ElMessage.error(e.message||'渠道回执处理失败')}finally{saving.value=false}}
async function submitChannelRefund(row){
 await runConfirmedChannelAction({
  busy:saving,
  confirm:()=>ElMessageBox.confirm('请确认售后金额、退货验收及原支付渠道均已核对。提交后等待渠道回执，不代表退款已经成功。','发起原路退款 · '+row.id,{confirmButtonText:'确认提交',cancelButtonText:'取消',type:'warning'}),
  submit:()=>channelRefund(row.id),
  success:async response=>{const feedback=channelSubmissionFeedback(response,'SUCCESS','已提交退款渠道，请等待回执确认');ElMessage[feedback.type](feedback.message);await load()},
  failure:e=>ElMessage.error(e.message||'退款提交或刷新失败，请重新查询售后状态')
 })
}
async function submitChannelPayout(row){
 await runConfirmedChannelAction({
  busy:saving,
  confirm:()=>ElMessageBox.confirm('请确认提现审核、金额及结算账户均已核对。提交后以渠道回执或本地沙盒结果为准，不代表真实到账。','发起渠道打款 · '+row.id,{confirmButtonText:'确认提交',cancelButtonText:'取消',type:'warning'}),
  submit:()=>channelPayout(row.id),
  success:async response=>{const feedback=channelSubmissionFeedback(response,'PAID','已提交打款渠道，请等待回执确认');ElMessage[feedback.type](feedback.message);await load()},
  failure:e=>ElMessage.error(e.message||'打款提交或刷新失败，请重新查询提现状态')
 })
}
async function exportRows(){if(exporting)return;exporting=true;try{const snapshot=workspaceExportSnapshot({shopId:shopId.value,resource:activeTab.value||config.path,title:config.title,filter:search.value,columns:columns.value,rows:filteredRows.value});await command('export-audit',{shopId:snapshot.shopId,resource:snapshot.resource,rowCount:snapshot.rows.length,filter:snapshot.filter});if(disposed)return;const cols=snapshot.columns;const escape=csvCell;const content='\ufeff'+[cols.map(c=>escape(c[1])).join(','),...snapshot.rows.map(r=>cols.map(c=>escape(workspaceExportCell(c,r,{module:props.module,labels,money}))).join(','))].join('\r\n');const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=snapshot.title+'.csv';a.click();URL.revokeObjectURL(url)}catch{return}finally{exporting=false}}
</script>
